import pyarrow.parquet as pq
t = pq.read_table('/root/autodl-tmp/libero_demos/libero_object_image/data/chunk-000/file-096.parquet')
print('shape:', t.num_rows, 'rows,', t.num_columns, 'cols')
print('columns:', t.column_names)
print('schema:')
for f in t.schema:
    print(f'  {f.name}: {f.type}')
row = t.slice(0, 1).to_pylist()[0]
for k, v in row.items():
    if isinstance(v, (bytes, bytearray)):
        print(f'  {k}: bytes(len={len(v)})')
    elif isinstance(v, dict):
        for kk, vv in v.items():
            print(f'  {k}.{kk}: {type(vv).__name__}', end='')
            if isinstance(vv, (bytes, bytearray)):
                print(f' bytes(len={len(vv)})')
            else:
                print(f' {vv}')
    elif isinstance(v, list):
        print(f'  {k}: list(len={len(v)}) = {v[:5]}...' if len(v) > 5 else f'  {k}: {v}')
    else:
        print(f'  {k}: {v}')
print('---')
print('episode_index unique:', sorted(set(t.column('episode_index').to_pylist()))[:10])
print('total episodes in file:', len(set(t.column('episode_index').to_pylist())))
"

